import React, { useMemo, useRef } from 'react'
import { useFrame, useLoader } from '@react-three/fiber'
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'

// Generated by tools/avatar/build_avatar.py (Blender, headless).
const MODEL = '/models/avatar.glb'

export const Avatar: React.FC<{
  onHover: (label: string | null) => void
  onClick: () => void
}> = ({ onHover, onClick }) => {
  const gltf = useLoader(GLTFLoader, MODEL)
  const body = useRef<THREE.Object3D | null>(null)

  const { scene, head } = useMemo(() => {
    const scene = gltf.scene.clone(true)
    scene.traverse((o) => {
      if (!(o as THREE.Mesh).isMesh) return
      // glasses are flagged in Blender: their shadow smears across the face at this scale
      o.castShadow = !o.userData.no_shadow
      o.receiveShadow = true
    })
    return { scene, head: scene.getObjectByName('Head') ?? null }
  }, [gltf])

  useFrame(({ clock, pointer }) => {
    const t = clock.elapsedTime
    if (head) {
      head.rotation.y = pointer.x * 0.16 + Math.sin(t * 0.6) * 0.03
      head.rotation.x = -pointer.y * 0.07
    }
    if (!body.current) body.current = scene.getObjectByName('Body') ?? null
    if (body.current) body.current.position.y = Math.sin(t * 1.5) * 0.012
  })

  return (
    <primitive
      object={scene}
      position={[1.35, 0.02, -1.6]}
      rotation={[0, -0.12, 0]}
      onPointerOver={(e: { stopPropagation: () => void }) => {
        e.stopPropagation()
        onHover('Off the clock')
      }}
      onPointerOut={(e: { stopPropagation: () => void }) => {
        e.stopPropagation()
        onHover(null)
      }}
      onClick={(e: { stopPropagation: () => void }) => {
        e.stopPropagation()
        onClick()
      }}
    />
  )
}
